package br.edu.ifrn.sistemachamados.controller;
import br.edu.ifrn.sistemachamados.dto.request.*;import br.edu.ifrn.sistemachamados.dto.response.*;import br.edu.ifrn.sistemachamados.mapper.ApiMapper;import br.edu.ifrn.sistemachamados.model.*;import br.edu.ifrn.sistemachamados.model.enums.*;import br.edu.ifrn.sistemachamados.service.*;import jakarta.validation.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/usuarios")public class UsuarioController{final UsuarioService s;public UsuarioController(UsuarioService s){this.s=s;}Usuario e(UsuarioRequest r){Usuario x=new Usuario();x.setNome(r.nome());x.setEmail(r.email());x.setMatricula(r.matricula());x.setTipo(r.tipo());if(r.setorId()!=null){Setor z=new Setor();z.setId(r.setorId());x.setSetor(z);}return x;}@PostMapping public ResponseEntity<UsuarioResponse>post(@Valid @RequestBody UsuarioRequest r){return ResponseEntity.status(201).body(ApiMapper.usuario(s.cadastrar(e(r))));}@GetMapping public PageResponse<UsuarioResponse>list(@RequestParam(required=false)String nome,@RequestParam(required=false)TipoUsuario tipo,@RequestParam(required=false)Long setorId,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size,@RequestParam(required=false)String[] sort){return PageResponse.of(s.listar(nome,tipo,setorId,WebSupport.page(page,size,sort)),ApiMapper::usuario);}@GetMapping("/{id}")public UsuarioResponse get(@PathVariable Long id){return ApiMapper.usuario(s.buscarPorId(id));}@PutMapping("/{id}")public UsuarioResponse put(@PathVariable Long id,@Valid @RequestBody UsuarioRequest r){return ApiMapper.usuario(s.atualizar(id,e(r)));}@GetMapping("/{id}/chamados")public PageResponse<ChamadoResponse>chamados(@PathVariable Long id,@RequestParam(required=false)StatusChamado status,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer size,@RequestParam(required=false)String[] sort){return PageResponse.of(s.listarChamados(id,status,WebSupport.page(page,size,sort)),ApiMapper::chamado);}}
